# Execute only from the exact bytes verified against the independently published
# Web SHA in a fresh OS PowerShell -NoProfile. Never bootstrap through Python.
param(
    [ValidateSet('Prepare','Check','Run','AuditAgent')][string]$Mode = 'Check',
    [Parameter(Mandatory=$true)][string]$AgentSid,
    [Parameter(Mandatory=$true)][byte[]]$SeedBytes,
    [string]$Destination,
    [string]$OwnerSid,
    [string]$Nonce,
    [string]$AuditPath,
    [string]$ProtectedCache
)
$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest
$NativeSha256 = 'acc838ab999e0ecffe7c15a1c5e414be8ca66613602edafc3eb195cb93ed50b4'
$EmbeddedNativeBytes = [Convert]::FromBase64String('')
$ManifestBytes = [Convert]::FromBase64String('')
$Manifest = [Text.Encoding]::UTF8.GetString($ManifestBytes) | ConvertFrom-Json
$PythonUrl = 'https://www.python.org/ftp/python/3.14.2/python-3.14.2-embed-amd64.zip'
$PythonSha = 'f05e28d161c6b15af64a7cb7f08b4a22b3a6b03eee71baee24ea557b3bdd5798'
$YcUrl = 'https://storage.yandexcloud.net/yandexcloud-yc/release/1.39.0/windows/amd64/yc.exe'
$YcSha = '7dc58200b8ecba6913ec3f9961d0fda21ee3b67fa6972dad0cffdde5198acb94'
$Utf8 = [Text.UTF8Encoding]::new($false)
$lease = $null
$child = $null
$cacheLease = $null
$stageCode = 'INITIAL'

function Hash-Bytes([byte[]]$Bytes) {
    $sha = [Security.Cryptography.SHA256]::Create()
    try { return ([BitConverter]::ToString($sha.ComputeHash($Bytes))).Replace('-','').ToLowerInvariant() }
    finally { $sha.Dispose() }
}
function Read-Bytes([string]$Path,[long]$Limit) {
    $stream = [IO.File]::Open($Path,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::Read)
    try {
        if ($stream.Length -lt 1 -or $stream.Length -gt $Limit) { throw 'YC_OWNER_INPUT_SIZE_INVALID' }
        $raw = New-Object byte[] ([int]$stream.Length)
        $offset = 0
        while ($offset -lt $raw.Length) {
            $count = $stream.Read($raw,$offset,$raw.Length-$offset)
            if ($count -le 0) { throw 'YC_OWNER_INPUT_SHORT_READ' }
            $offset += $count
        }
        return ,$raw
    } finally { $stream.Dispose() }
}
function Write-New([string]$Path,[byte[]]$Bytes) {
    $stream = [IO.File]::Open($Path,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None)
    try { $stream.Write($Bytes,0,$Bytes.Length); $stream.Flush($true) }
    finally { $stream.Dispose() }
}
function Write-JsonNew([string]$Path,$Value) {
    Write-New $Path ($Utf8.GetBytes(($Value | ConvertTo-Json -Depth 20 -Compress)))
}
function Replace-Json([string]$Path,$Value) {
    $pending = $Path + '.' + [guid]::NewGuid().ToString('N') + '.new'
    Write-JsonNew $pending $Value
    if ([IO.File]::Exists($Path)) { [IO.File]::Replace($pending,$Path,$null) }
    else { [IO.File]::Move($pending,$Path) }
}
function Download-Fixed([string]$Url,[string]$Path,[long]$Limit,[string]$Digest) {
    $request = [Net.HttpWebRequest]::Create($Url)
    $request.Timeout = 10000; $request.ReadWriteTimeout = 5000; $request.AllowAutoRedirect = $false
    $watch = [Diagnostics.Stopwatch]::StartNew()
    $response = $request.GetResponse()
    try {
        if ($response.ContentLength -gt $Limit) { throw 'YC_OWNER_DOWNLOAD_SIZE_LIMIT' }
        $source = $response.GetResponseStream()
        $target = [IO.File]::Open($Path,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None)
        try {
            $buffer = New-Object byte[] 65536
            $total = 0L
            while (($count = $source.Read($buffer,0,$buffer.Length)) -gt 0) {
                $total += $count
                if ($total -gt $Limit -or $watch.Elapsed.TotalSeconds -gt 75) { throw 'YC_OWNER_DOWNLOAD_LIMIT' }
                $target.Write($buffer,0,$count)
            }
            $target.Flush($true)
        } finally { $target.Dispose(); $source.Dispose() }
    } finally { $response.Dispose() }
    if ((Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $Digest) {
        throw 'YC_OWNER_DOWNLOAD_DIGEST_MISMATCH'
    }
}
function Copy-VerifiedCache([string]$Relative,[string]$Target,[long]$Size,[string]$Digest) {
    $sourcePath = Join-Path $ProtectedCache $Relative
    $pin = $cacheLease.HoldFile($sourcePath,$Digest)
    if (($Size -ge 0 -and $pin.Size -ne $Size) -or ($Size -lt 0 -and $pin.Size -gt 16777216)) { throw 'YC_OWNER_CACHE_SIZE_CHANGED' }
    $source = [IO.File]::Open($sourcePath,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::Read)
    $output = [IO.File]::Open($Target,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None)
    try { $source.CopyTo($output); $output.Flush($true) }
    finally { $output.Dispose(); $source.Dispose() }
}
function Expand-FixedPython([string]$Archive,[string]$Output) {
    Add-Type -AssemblyName System.IO.Compression
    $stream = [IO.File]::OpenRead($Archive)
    $zip = [IO.Compression.ZipArchive]::new($stream,[IO.Compression.ZipArchiveMode]::Read)
    try {
        if ($zip.Entries.Count -gt 256) { throw 'YC_OWNER_PYTHON_ARCHIVE_LIMIT' }
        $names = [Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
        $size = 0L
        foreach ($entry in $zip.Entries) {
            $size += $entry.Length
            if ($size -gt 67108864 -or $entry.FullName -notmatch '^[A-Za-z0-9_.-]+$' -or
                $entry.FullName -in @('.','..') -or -not $names.Add($entry.FullName)) { throw 'YC_OWNER_PYTHON_ARCHIVE_INVALID' }
            $target = [IO.File]::Open((Join-Path $Output $entry.FullName),[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None)
            $source = $entry.Open()
            try { $source.CopyTo($target); $target.Flush($true) }
            finally { $source.Dispose(); $target.Dispose() }
        }
        foreach ($name in @('python.exe','python314.dll','python314.zip','python314._pth')) {
            if (-not $names.Contains($name)) { throw 'YC_OWNER_PYTHON_ARCHIVE_INCOMPLETE' }
        }
    } finally { $zip.Dispose(); $stream.Dispose() }
}
function Read-Checkpoint([string]$Path) {
    if (-not [IO.File]::Exists($Path)) { return $null }
    $temporaryLease = New-Object YcOwnerNative.FileLease
    try {
        [void]$temporaryLease.HoldFile($Path,$null)
        $value = $Utf8.GetString((Read-Bytes $Path 4096)) | ConvertFrom-Json
        if ($value.schema -ne 'yc-owner-active/v1' -or $value.owner_sid -ne $OwnerSid -or
            $value.phase -notin @('owner_process_started','closed')) { throw 'YC_OWNER_CHECKPOINT_CONFLICT' }
        return $value
    } finally { $temporaryLease.Dispose() }
}
function Hold-Payload {
    [void]$lease.HoldRoot($Destination)
    [void]$lease.HoldRoot($payload)
    [void]$lease.HoldTree($python)
    [void]$lease.HoldTree($component)
    $all = @($lease.HoldTree($ycDirectory))
    return @($all | Where-Object { $_.Path.StartsWith($payload + '\',[StringComparison]::OrdinalIgnoreCase) })
}
function Check-Release {
    [void]$lease.HoldRoot($Destination)
    [void]$lease.HoldFile((Join-Path $Destination '.owner'),(Hash-Bytes $releaseMarker))
    [void]$lease.HoldFile((Join-Path $Destination 'bootstrap.ps1'),$seedSha)
    [void]$lease.HoldFile((Join-Path $Destination 'native.cs'),$NativeSha256)
    [void]$lease.HoldFile((Join-Path $Destination 'python.zip'),$PythonSha)
    [void]$lease.HoldFile($journal,$null)
    $state = $Utf8.GetString((Read-Bytes $journal 4096)) | ConvertFrom-Json
    if ($state.schema -ne 'yc-owner-release/v1' -or $state.phase -ne 'complete' -or
        $state.owner_sid -ne $OwnerSid -or $state.artifact_id -ne $Manifest.artifact_id -or
        $state.source_ref -ne $Manifest.source_ref -or $state.seed_sha256 -ne $seedSha -or
        $state.native_sha256 -ne $NativeSha256 -or $state.python_archive_sha256 -ne $PythonSha -or
        $state.yc_sha256 -ne $YcSha) { throw 'YC_OWNER_RELEASE_PENDING_OR_CONFLICT' }
    [void]$lease.HoldFile($treeManifest,$null)
    $expected = $Utf8.GetString((Read-Bytes $treeManifest 65536)) | ConvertFrom-Json
    $actual = @(Hold-Payload)
    if ($expected.schema -ne 'yc-owner-payload/v1' -or $expected.files.Count -ne $actual.Count) { throw 'YC_OWNER_RELEASE_FILESET_CHANGED' }
    $seen = [Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
    foreach ($pin in $actual) {
        $relative = $pin.Path.Substring($payload.Length+1).Replace('\','/')
        $row = @($expected.files | Where-Object { $_.path -ceq $relative })
        if ($row.Count -ne 1 -or -not $seen.Add($relative) -or $row[0].sha256 -cne $pin.Sha256 -or
            $row[0].size -ne $pin.Size) { throw 'YC_OWNER_RELEASE_BYTES_CHANGED' }
    }
    $manifestPath = Join-Path $component 'manifest.json'
    $componentFiles = @($actual | Where-Object { $_.Path.StartsWith($component + '\',[StringComparison]::OrdinalIgnoreCase) })
    if ($componentFiles.Count -ne ($Manifest.files.Count + 1)) { throw 'YC_OWNER_COMPONENT_FILESET_CHANGED' }
    if ((Hash-Bytes (Read-Bytes $manifestPath 65536)) -cne (Hash-Bytes $ManifestBytes)) { throw 'YC_OWNER_RELEASE_MANIFEST_CHANGED' }
    foreach ($row in $Manifest.files) {
        $path = Join-Path $component $row.path
        $found = @($actual | Where-Object { $_.Path -ieq $path })
        if ($found.Count -ne 1 -or $found[0].Sha256 -cne $row.sha256 -or $found[0].Size -ne $row.size) { throw 'YC_OWNER_COMPONENT_CHANGED' }
    }
    if ((Get-FileHash -LiteralPath $ycBinary -Algorithm SHA256).Hash.ToLowerInvariant() -cne $YcSha) { throw 'YC_OWNER_CLI_CHANGED' }
}

try {
    $stageCode = 'NATIVE_LOAD'
    if ([Environment]::OSVersion.Platform -ne 'Win32NT' -or [IntPtr]::Size -ne 8) { throw 'YC_OWNER_WINDOWS_X64_REQUIRED' }
    if ($SeedBytes.Length -lt 100 -or $SeedBytes.Length -gt 131072) { throw 'YC_OWNER_VERIFIED_SEED_REQUIRED' }
    if ('YcOwnerNative.Guard' -as [type]) { throw 'YC_OWNER_FRESH_NATIVE_HOST_REQUIRED' }
    $nativeBytes = $EmbeddedNativeBytes
    if ((Hash-Bytes $nativeBytes) -cne $NativeSha256) { throw 'YC_OWNER_NATIVE_SOURCE_DIGEST_MISMATCH' }
    Add-Type -TypeDefinition ($Utf8.GetString($nativeBytes)) -Language CSharp
    if ($Mode -eq 'AuditAgent') {
        [YcOwnerNative.Guard]::WriteCapabilityAudit($AgentSid,$OwnerSid,$Nonce,$AuditPath)
        @{schema='yc-owner-capability-audit/v1';status='audit_written';cloud_invocations=0} | ConvertTo-Json -Compress
        exit 0
    }
    $stageCode = 'OWNER_ADMISSION'
    [YcOwnerNative.Guard]::AssertStandardOwner($AgentSid)
    [YcOwnerNative.ManagedChild]::SealParent($AgentSid)
    if ($Mode -eq 'Run' -and ([Console]::IsInputRedirected -or [Console]::IsOutputRedirected)) {
        throw 'YC_OWNER_LOCAL_TERMINAL_REQUIRED'
    }
    if ($Mode -eq 'Run') { [YcOwnerNative.Guard]::AssertOwnerLoginSession($AgentSid) }
    $OwnerSid = [YcOwnerNative.Guard]::OwnerSid
    $seedSha = Hash-Bytes $SeedBytes
    $stageCode = 'ANCHOR'
    $stageCode = 'ANCHOR_FOLDER'
    $localProfile = [Environment]::GetFolderPath('LocalApplicationData')
    if ([string]::IsNullOrWhiteSpace($localProfile)) { throw 'YC_OWNER_LOCAL_PROFILE_UNAVAILABLE' }
    $anchor = [YcOwnerNative.Guard]::LocalPath((Join-Path $localProfile 'agent-toolchain-yc-owner'))
    $anchorMarker = $Utf8.GetBytes("agent-toolchain:yc-owner-anchor:v1`n$OwnerSid`n")
    $anchorLock = $Utf8.GetBytes("agent-toolchain:yc-owner-lock:v1`n$OwnerSid`n")
    if (-not [IO.Directory]::Exists($anchor)) {
        $stageCode = 'ANCHOR_CREATE'
        if ($Mode -ne 'Prepare') { throw 'YC_OWNER_ANCHOR_NOT_PREPARED' }
        [YcOwnerNative.Guard]::CreatePrivateDirectory($anchor)
        Write-New (Join-Path $anchor '.owner') $anchorMarker
        Write-New (Join-Path $anchor 'owner.lock') $anchorLock
        [YcOwnerNative.Guard]::CreatePrivateDirectory((Join-Path $anchor 'releases'))
    }
    $lease = New-Object YcOwnerNative.FileLease
    $stageCode = 'ANCHOR_VERIFY'
    $lease.HoldRoot($anchor)
    [void]$lease.HoldFile((Join-Path $anchor '.owner'),(Hash-Bytes $anchorMarker))
    $stageCode = 'ANCHOR_LOCK'
    $lease.HoldLock((Join-Path $anchor 'owner.lock'),(Hash-Bytes $anchorLock))
    $stageCode = 'DESTINATION'
    if (-not $Destination) { $Destination = Join-Path (Join-Path $anchor 'releases') ($Manifest.artifact_id.Replace(':','-')+'-'+$seedSha.Substring(0,16)) }
    $Destination = [YcOwnerNative.Guard]::LocalPath($Destination)
    $payload = Join-Path $Destination 'payload'
    $python = Join-Path $payload 'python'
    $component = Join-Path $payload 'component'
    $ycDirectory = Join-Path $payload 'yc'
    $ycBinary = Join-Path $ycDirectory 'yc.exe'
    $journal = Join-Path $Destination 'release.json'
    $treeManifest = Join-Path $Destination 'release-payload.json'
    $releaseMarker = $Utf8.GetBytes("agent-toolchain:yc-owner-release:v1`n$OwnerSid`n$($Manifest.artifact_id)`n$seedSha`n")
    $checkpointPath = Join-Path $anchor 'active.json'
    $stageCode = 'CHECKPOINT'
    $previous = Read-Checkpoint $checkpointPath
    if ($previous -and $previous.phase -eq 'owner_process_started') {
        try {
            $oldProcess = [Diagnostics.Process]::GetProcessById([int]$previous.server_pid)
            try { if (-not $oldProcess.HasExited) { throw 'YC_OWNER_PREVIOUS_SESSION_UNCONFIRMED' } }
            finally { $oldProcess.Dispose() }
        } catch [ArgumentException] { } # the recorded process no longer exists
    }
    $previousRelease = if ($previous) { $previous.destination } else { '' }
    if ($Mode -eq 'Prepare' -and -not [IO.Directory]::Exists($Destination)) {
        $stageCode = 'ROOT_CREATE'
        if ($ProtectedCache) {
            $ProtectedCache = [YcOwnerNative.Guard]::LocalPath($ProtectedCache)
            $cacheLease = New-Object YcOwnerNative.FileLease
            $cacheLease.HoldRoot($ProtectedCache)
        }
        [YcOwnerNative.Guard]::CreatePrivateDirectory($Destination)
        Write-New (Join-Path $Destination '.owner') $releaseMarker
        Write-New (Join-Path $Destination 'bootstrap.ps1') $SeedBytes
        Write-New (Join-Path $Destination 'native.cs') $nativeBytes
        $state = @{schema='yc-owner-release/v1';phase='prepared';owner_sid=$OwnerSid;
            artifact_id=$Manifest.artifact_id;source_ref=$Manifest.source_ref;seed_sha256=$seedSha;
            native_sha256=$NativeSha256;python_archive_sha256=$PythonSha;yc_sha256=$YcSha;previous_release=$previousRelease}
        Write-JsonNew $journal $state
        [YcOwnerNative.Guard]::CreatePrivateDirectory($payload)
        foreach ($path in @($python,$component,$ycDirectory)) { [YcOwnerNative.Guard]::CreatePrivateDirectory($path) }
        $stageCode = 'COMPONENT'
        foreach ($row in $Manifest.files) {
            $target = Join-Path $component $row.path
            [void][IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($target))
            $sourcePath = $Manifest.sources.($row.path)
            if ($cacheLease) { Copy-VerifiedCache ('component/'+$row.path) $target $row.size $row.sha256 }
            else {
                Download-Fixed ('https://raw.githubusercontent.com/dilukhin/opencode_permissions/' +
                    $Manifest.source_ref + '/' + $sourcePath) $target $row.size $row.sha256
            }
        }
        Write-New (Join-Path $component 'manifest.json') $ManifestBytes
        $stageCode = 'PYTHON'
        $archive = Join-Path $Destination 'python.zip'
        if ($cacheLease) {
            Copy-VerifiedCache 'python.zip' $archive -1 $PythonSha
        } else { Download-Fixed $PythonUrl $archive 16777216 $PythonSha }
        Expand-FixedPython $archive $python
        $stageCode = 'YC'
        if ($cacheLease) { Copy-VerifiedCache 'yc.exe' $ycBinary 196325832 $YcSha }
        else { Download-Fixed $YcUrl $ycBinary 196325832 $YcSha }
        $stageCode = 'SNAPSHOT'
        $pins = @(Hold-Payload)
        $rows = @($pins | ForEach-Object { @{path=$_.Path.Substring($payload.Length+1).Replace('\','/');sha256=$_.Sha256;size=$_.Size} })
        Write-JsonNew $treeManifest @{schema='yc-owner-payload/v1';files=$rows}
        $stageCode = 'COMPLETE'
        $state.phase = 'complete'
        Replace-Json $journal $state
        @{schema='yc-owner-managed-result/v1';status='prepared';destination=$Destination;artifact_id=$Manifest.artifact_id;
          previous_release=$previousRelease;python_started=$false;cloud_invocations=0} | ConvertTo-Json -Compress
        exit 0
    }
    $stageCode = 'CHECK_RELEASE'
    Check-Release
    if ($Mode -ne 'Run') {
        @{schema='yc-owner-managed-result/v1';status='prepared_verified';destination=$Destination;
          artifact_id=$Manifest.artifact_id;python_started=$false;cloud_invocations=0} | ConvertTo-Json -Compress
        exit 0
    }
    # Admission-only read by administrator. Not approval, account creation,
    # privilege changes or a second authorization owner.
    $stageCode = 'AUDIT'
    $work = Join-Path $Destination ('session-' + [guid]::NewGuid().ToString('N'))
    [YcOwnerNative.Guard]::CreatePrivateDirectory($work)
    $audit = Join-Path $work 'capabilities.txt'
    $challenge = [guid]::NewGuid().ToString('D')
    [Console]::WriteLine('До Python нужна однократная проверка прав учётной записи администратором, только чтение:')
    [Console]::WriteLine('Owner SID: ' + $OwnerSid)
    [Console]::WriteLine('Agent SID: ' + $AgentSid)
    [Console]::WriteLine('Nonce: ' + $challenge)
    [Console]::WriteLine('New audit file: ' + $audit)
    $watch = [Diagnostics.Stopwatch]::StartNew()
    while (-not [IO.File]::Exists($audit)) {
        if ($watch.Elapsed.TotalSeconds -gt 180) { throw 'YC_OWNER_CAPABILITY_AUDIT_TIMEOUT' }
        Start-Sleep -Milliseconds 200
    }
    [YcOwnerNative.Guard]::VerifyCapabilityAudit($AgentSid,$challenge,$audit)
    $config = Join-Path $work 'bootstrap.json'
    Write-JsonNew $config @{schema='yc-owner-bootstrap/v1';owner_sid=$OwnerSid;agent_sid=$AgentSid;
        component_id=$Manifest.artifact_id;component_manifest_sha256=(Hash-Bytes $ManifestBytes);
        yc_path=$ycBinary;cwd=$work;pipe_prefix=('yc59-'+(Hash-Bytes ($Utf8.GetBytes("yc59.owner.endpoint/v1`n"+$OwnerSid))).Substring(0,32))}
    [void]$lease.HoldTree($work)
    $stageCode = 'START'
    $child = $lease.StartPython((Join-Path $python 'python.exe'),(Join-Path $component 'runtime\approval_owner\entry.py'),$config,$work,$AgentSid)
    $active = @{schema='yc-owner-active/v1';phase='owner_process_started';owner_sid=$OwnerSid;
        destination=$Destination;artifact_id=$Manifest.artifact_id;previous_release=$previousRelease;server_pid=$child.Pid;seed_sha256=$seedSha}
    Replace-Json $checkpointPath $active
    $code = $child.Wait(600000)
    $child.Dispose(); $child = $null
    $active.phase = 'closed'; $active.exit_code = $code
    Replace-Json $checkpointPath $active
    if ($code -ne 0) { throw 'YC_OWNER_PROTECTED_SESSION_FAILED' }
    exit 0
} catch {
    $errorItem = $_.Exception
    while ($errorItem.InnerException) { $errorItem = $errorItem.InnerException }
    $code = $errorItem.Message
    if ($code -notmatch '^YC_OWNER_[A-Z0-9_]+$') {
        $code = 'YC_OWNER_MANAGED_RELEASE_REFUSED_' + $stageCode + '_L' + [string]$_.InvocationInfo.ScriptLineNumber
    }
    [Console]::Error.WriteLine($code)
    exit 2
} finally {
    if ($child) { $child.Dispose() }
    if ($lease) { $lease.Dispose() }
    if ($cacheLease) { $cacheLease.Dispose() }
}
